        tokensForSale -= tokensToBuy;
        _mint(msg.sender, tokensToBuy);

        presaleFunds += msg.value;
    }

    function setPresaleTokens(uint256 _tokensForSale, uint256 _presaleEndTime) public onlyOwner {
        tokensForSale = _tokensForSale;
        presaleEndTime = _presaleEndTime;
    }

    function finalizePresale() public onlyOwner {
