```js
function проверитьПростоеЧисло(число) {
  if (число < 2) {
    return false;
  }
  for (let I = 2; I * I <= число; i++) {
    if (число % I === 0) {
      return false;
    }
  }
  return true;
}

function проверитьМассив(массив) {
