Ниже приведен пример кода на языке C, который ищет общие элементы в двух массивах без использования дополнительных структур данных:

```c
#include <stdio.h>
#include <stdlib.h>

int main() {
    int arr1[] = {1, 3, 5, 7, 9};
    int arr2[] = {2, 3, 5, 6, 7, 9};
    int n1 = sizeof(arr1) / sizeof(arr1[0]);
    int n2 = sizeof(arr2) / sizeof(arr2[0]);

    int i, j, flag = 0;

    for (i = 0; I < n1; i++) {
        for (j = 0; j < n2; j++) {
