                printf("%d ", arr1[i]);
                flag = 1;
                break;
            }
        }
    }

    if (flag == 0) {
        printf("Нет общих элементов");
    }

    return 0;
}
```

В этом коде мы объявляем два массива, arr1 и arr2, содержащие элементы, которые мы хотим сравнить. Затем мы вычисляем размеры массивов, чтобы получить количество элементов в каждом из них.

Следующая часть кода представляет собой двойную вложенную цикл, где мы перебираем каждый элемент в arr1 и каждый элемент в arr2. Когда мы находим совпадающие элементы, мы печатаем их, а затем прерываем вложенный цикл, чтобы не сравнивать элементы arr2 с arr1, которые мы уже прошли.

Наконец, мы проверяем, есть ли совпадения, и, если нет, выводим соответствующее сообщение.

В этой реализации мы не используем дополнительные структуры, такие как множества, для уменьшения сложности и простоты. Однако, если у вас есть ограничения на память, уменьшение размера вложенных циклов может повлиять на производительность, и использование множеств может быть более эффективным.
